command:
find /work -type f \( -iname .env -o -iname '.env.*' \) | while IFS= read -r f; do REL="${f#/work/}" awk 'function hex(s, out, i) { out = ""; for (i = 1; i <= length(s); i++) out = out sprintf("%02x", ord[substr(s, i, 1)]); return out } BEGIN { for (i = 1; i < 256; i++) ord[sprintf("%c", i)] = i; file = hex(ENVIRON["REL"]) } /^[ \t]*(#.*)?$/ { print; next } match($0, /^[ \t]*(export[ \t]+)?[A-Za-z_][A-Za-z0-9_.-]*[ \t]*=/) { head = substr($0, 1, RLENGTH); name = head; sub(/^[ \t]*(export[ \t]+)?/, "", name); sub(/[ \t]*=$/, "", name); print head "./daodan-dotenv-" file "-" hex(name) }' "$f" > "$f.daodan" && mv -f "$f.daodan" "$f"; done
mkdir -p /daodan/state/results/0; (cd /work && exec env PATH=/daodan/state/tools/bin:/daodan/state/tools/node/bin:/daodan/state/tools/npm/bin:/daodan/state/tools/go/bin:/daodan/state/tools/rust/bin:/daodan/state/tools/cmake/bin:/opt/java/openjdk/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin HOME=/daodan/state/home GOPATH=/daodan/state/go GOCACHE=/daodan/state/go-build GOTELEMETRY=off CARGO_HOME=/daodan/state/cargo UV_CACHE_DIR=/daodan/state/uv npm_config_cache=/daodan/state/npm-cache npm_config_update_notifier=false VCPKG_ROOT=/daodan/state/tools/vcpkg VCPKG_DISABLE_METRICS=1 VCPKG_BINARY_SOURCES=clear CONAN_HOME=/daodan/state/conan-home sh -c '( mkdir -p /daodan/state/tools/bin /daodan/state/home ) && ( if [ ! -x /daodan/state/jdk/bin/java ] && [ -f /daodan/state/in/temurin-17.tar.gz ]; then
  mkdir -p /daodan/state/jdk && tar -xzf /daodan/state/in/temurin-17.tar.gz -C /daodan/state/jdk --strip-components=1 && rm -f /daodan/state/in/temurin-17.tar.gz
fi
mkdir -p /opt/java && ln -sfn /daodan/state/jdk /opt/java/openjdk
 ) && ( cd /daodan/state/tools && jar xf /daodan/state/in/gradle.zip && chmod 755 /daodan/state/tools/gradle-9.9.1/bin/gradle && ln -sf /daodan/state/tools/gradle-9.9.1/bin/gradle /daodan/state/tools/bin/gradle )') > /daodan/state/results/0/stdout 2> /daodan/state/results/0/stderr; echo $? > /daodan/state/results/0/code
mkdir -p /daodan/state/results/1; (cd /work/android && exec env PATH=/daodan/state/tools/bin:/daodan/state/tools/node/bin:/daodan/state/tools/npm/bin:/daodan/state/tools/go/bin:/daodan/state/tools/rust/bin:/daodan/state/tools/cmake/bin:/opt/java/openjdk/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin HOME=/daodan/state/home GOPATH=/daodan/state/go GOCACHE=/daodan/state/go-build GOTELEMETRY=off CARGO_HOME=/daodan/state/cargo UV_CACHE_DIR=/daodan/state/uv npm_config_cache=/daodan/state/npm-cache npm_config_update_notifier=false VCPKG_ROOT=/daodan/state/tools/vcpkg VCPKG_DISABLE_METRICS=1 VCPKG_BINARY_SOURCES=clear CONAN_HOME=/daodan/state/conan-home GRADLE_OPTS=-Xmx512m LC_ALL=C.UTF-8 sh -c 'if [ ! -x /daodan/state/jdk/bin/java ] && [ -f /daodan/state/in/temurin-17.tar.gz ]; then
  mkdir -p /daodan/state/jdk && tar -xzf /daodan/state/in/temurin-17.tar.gz -C /daodan/state/jdk --strip-components=1 && rm -f /daodan/state/in/temurin-17.tar.gz
fi
mkdir -p /opt/java && ln -sfn /daodan/state/jdk /opt/java/openjdk
if [ -n "${HTTPS_PROXY:-}" ]; then a=${HTTPS_PROXY#*://}; a=${a%%/*}; h=${a%:*}; p=${a##*:}; export JAVA_TOOL_OPTIONS="${JAVA_TOOL_OPTIONS:-} -Duser.home=$HOME -Dhttps.proxyHost=$h -Dhttps.proxyPort=$p -Dhttp.proxyHost=$h -Dhttp.proxyPort=$p"; mkdir -p "$HOME/.m2"; printf "%s\n" "<settings><proxies>" "<proxy><id>https</id><protocol>https</protocol><host>$h</host><port>$p</port></proxy>" "<proxy><id>http</id><protocol>http</protocol><host>$h</host><port>$p</port></proxy>" "</proxies></settings>" > "$HOME/.m2/settings.xml"; fi; exec "$@"' gradle sh -c 'i=$(mktemp) && printf %s "$1" > "$i" && exec gradle --no-daemon --console=plain -q --init-script "$i" help' gradle '// Daodan'"'"'s pre-map: Gradle'"'"'s project tree once the settings are evaluated, then per configured project the
// projects it depends on and the Java and Kotlin targets the build sets; with each, the URLs of the repositories it
// resolves from. Each record is a line starting with \u001e.
import groovy.json.JsonOutput
def emit(record) { println '"'"'\u001e'"'"' + JsonOutput.toJson(record) }
def urls(Closure repositories) {  // the Maven and Ivy repositories'"'"' URLs; none where the container does not exist
    try { return repositories().findAll { it.hasProperty('"'"'url'"'"') && it.url != null }.collect { it.url.toString() } }
    catch (Throwable ignored) { return [] }
}
def tree
tree = { d -> [[path: d.path, dir: d.projectDir.absolutePath, buildFile: d.buildFile.absolutePath,
                buildFileExists: d.buildFile.exists()]] + d.children.sort { it.path }.collectMany { tree(it) } }
def explicitValue(property) {  // the value the build set, never a convention (Gradle'"'"'s internal state of a Property)
    try {
        def field = org.gradle.api.internal.provider.AbstractProperty.getDeclaredField('"'"'state'"'"')
        field.accessible = true
        return field.get(property).isExplicit() ? property.getOrNull() : null
    } catch (Throwable ignored) { return null }
}
def text(value) { value == null ? null : (value.hasProperty('"'"'target'"'"') ? value.target : value.toString()) }
def compatibility(task, name) {  // a compile task'"'"'s own field, null under the java extension'"'"'s convention
    try {
        def field = org.gradle.api.tasks.compile.AbstractCompile.getDeclaredField(name)
        field.accessible = true
        return field.get(task)
    } catch (Throwable ignored) { return null }
}
def jvmTarget(options) {
    options != null && options.hasProperty('"'"'jvmTarget'"'"') ? text(explicitValue(options.jvmTarget)) : null
}
settingsEvaluated { s ->
    emit([kind: '"'"'build'"'"', root: s.rootDir.absolutePath, name: s.rootProject.name, nested: s.gradle.parent != null,
          gradle: s.gradle.gradleVersion, projects: tree(s.rootProject),
          repositories: urls { s.pluginManagement.repositories } + urls { s.dependencyResolutionManagement.repositories }])
}
gradle.projectsEvaluated { g ->
    def build = g.parent == null ? null : g.rootProject.name
    g.rootProject.allprojects { p ->
        if (!p.buildFile.exists()) { return }
        def facts = [:]
        def java = p.extensions.findByName('"'"'java'"'"')
        if (java != null) {
            facts['"'"'java.toolchain.languageVersion'"'"'] = text(explicitValue(java.toolchain.languageVersion))
            ['"'"'sourceCompatibility'"'"', '"'"'targetCompatibility'"'"'].each { name ->
                def raw = '"'"'raw'"'"' + name.capitalize()
                facts['"'"'java.'"'"' + name] = java.hasProperty(raw) ? text(java."$raw") : null
            }
        }
        p.tasks.withType(JavaCompile).each { t ->
            facts['"'"'options.release'"'"'] = facts['"'"'options.release'"'"'] ?: text(explicitValue(t.options.release))
            ['"'"'sourceCompatibility'"'"', '"'"'targetCompatibility'"'"'].each { name -> facts[name] = facts[name] ?: compatibility(t, name) }
        }
        def kotlin = p.extensions.findByName('"'"'kotlin'"'"')
        if (kotlin != null && kotlin.hasProperty('"'"'compilerOptions'"'"')) {
            facts['"'"'kotlin.compilerOptions.jvmTarget'"'"'] = jvmTarget(kotlin.compilerOptions)
        }
        p.tasks.names.findAll { it ==~ /compile\w*Kotlin\w*/ }.collect { p.tasks.getByName(it) }.each { t ->
            if (t.hasProperty('"'"'compilerOptions'"'"')) {
                facts['"'"'compilerOptions.jvmTarget'"'"'] = facts['"'"'compilerOptions.jvmTarget'"'"'] ?: jvmTarget(t.compilerOptions)
            }
        }
        def android = p.extensions.findByName('"'"'android'"'"')
        if (android != null) {  // the SDK platform and build tools the Android plugin compiles with, the build tools
            // its own default when the build sets none; '"'"''"'"' when its model gives none (an add-on'"'"'s target)
            def value = { name ->
                try { return android.hasProperty(name) ? android."$name" : null }
                catch (Throwable ignored) { return null }
            }
            def level = value('"'"'compileSdk'"'"'), minor = value('"'"'compileSdkMinor'"'"'), extension = value('"'"'compileSdkExtension'"'"')
            facts['"'"'android.compileSdk'"'"'] = level == null ? (value('"'"'compileSdkPreview'"'"') ?: '"'"''"'"')
                : "$level${minor ? '"'"'.'"'"' + minor : '"'"''"'"'}${extension ? '"'"'-ext'"'"' + extension : '"'"''"'"'}".toString()
            facts['"'"'android.buildToolsVersion'"'"'] = value('"'"'buildToolsVersion'"'"') ?: '"'"''"'"'
        }
        def uses = [] as SortedSet
        p.configurations.each { c ->
            c.dependencies.withType(org.gradle.api.artifacts.ProjectDependency).each { d -> uses << d.path }
        }
        uses.remove(p.path)
        emit([kind: '"'"'project'"'"', build: build, path: p.path, buildFile: p.buildFile.absolutePath,
              uses: uses as List, facts: facts.findAll { it.value != null },
              repositories: urls { p.repositories } + urls { p.buildscript.repositories }])
    }
}
') > /daodan/state/results/1/stdout 2> /daodan/state/results/1/stderr; echo $? > /daodan/state/results/1/code
exit 0
